package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type OrderRec struct {
	OrId    string
	OrStat  string
	OrQty   int64
	OrPrice decimal.Decimal
}

var WsEofFlag string = "N"
var WsTotal decimal.Decimal = decimal.Zero
var WsGrand decimal.Decimal = decimal.Zero
var WsNewCount int64 = 0
var WsShipCount int64 = 0
var WsCancelCount int64 = 0
var WsInvalid int64 = 0
var WsBadQty int64 = 0
var WsQtyEd string
var WsPriceEd string
var WsTotalEd string
var WsGrandEd string

var curRec OrderRec
var inputLines []string
var inputIdx int

func loadInput() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = []string{}
			return
		}
		fmt.Fprintf(os.Stderr, "open input.dat: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	scanner.Buffer(make([]byte, 0, 64*1024), 10*1024*1024)
	var lines []string
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintf(os.Stderr, "read input.dat: %v\n", err)
		os.Exit(1)
	}
	inputLines = lines
}

func parseQtyField(s string) int64 {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return 0
	}
	digits := ""
	for _, r := range trim {
		if r >= '0' && r <= '9' {
			digits += string(r)
		}
	}
	if digits == "" {
		return 0
	}
	v, _ := strconv.ParseInt(digits, 10, 64)
	return v
}

func parsePriceField(s string) decimal.Decimal {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return decimal.Zero
	}
	digits := ""
	for _, r := range trim {
		if r >= '0' && r <= '9' {
			digits += string(r)
		}
	}
	if digits == "" {
		return decimal.Zero
	}
	n, _ := strconv.ParseInt(digits, 10, 64)
	return decimal.New(n, -2)
}

func storeValue(val decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	scaled := val.Shift(int32(scale))
	power := decimal.NewFromInt(1).Shift(int32(intDigits + scale))
	mod := scaled.Mod(power)
	res := mod.Shift(int32(-scale))
	if res.IsZero() {
		return decimal.Zero
	}
	return res
}

func storeTotal(v decimal.Decimal) decimal.Decimal {
	return storeValue(v, 8, 2)
}
func storeGrand(v decimal.Decimal) decimal.Decimal {
	return storeValue(v, 10, 2)
}

func formatEdited(val decimal.Decimal, pic string) string {
	var leftPic, rightPic string
	scale := 0
	if strings.Contains(pic, ".") {
		parts := strings.SplitN(pic, ".", 2)
		leftPic = parts[0]
		rightPic = parts[1]
		for _, ch := range rightPic {
			if ch == 'Z' || ch == '9' {
				scale++
			}
		}
	} else {
		leftPic = pic
		rightPic = ""
		scale = 0
	}
	intDigits := 0
	for _, ch := range leftPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	isNeg := val.IsNegative()
	absVal := val.Abs()

	var intStr, fracStr string
	if scale > 0 {
		rounded := absVal.Round(int32(scale))
		s := rounded.StringFixed(int32(scale))
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) > 1 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", scale)
		}
		if len(fracStr) < scale {
			fracStr = fracStr + strings.Repeat("0", scale-len(fracStr))
		} else if len(fracStr) > scale {
			fracStr = fracStr[:scale]
		}
	} else {
		rounded := absVal.Round(0)
		s := rounded.StringFixed(0)
		intStr = s
		fracStr = ""
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	if len(intStr) < intDigits {
		intStr = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	var leftBuilder strings.Builder
	nonZeroSeen := false
	intIdx := 0
	for _, ch := range leftPic {
		if ch == 'Z' || ch == '9' {
			digit := intStr[intIdx]
			intIdx++
			if ch == 'Z' {
				if digit != '0' {
					leftBuilder.WriteByte(digit)
					nonZeroSeen = true
				} else {
					if nonZeroSeen {
						leftBuilder.WriteByte('0')
					} else {
						leftBuilder.WriteByte(' ')
					}
				}
			} else {
				leftBuilder.WriteByte(digit)
				if digit != '0' {
					nonZeroSeen = true
				}
			}
		} else if ch == ',' {
			if nonZeroSeen {
				leftBuilder.WriteByte(',')
			} else {
				leftBuilder.WriteByte(' ')
			}
		} else {
			leftBuilder.WriteByte(byte(ch))
		}
	}
	leftResult := leftBuilder.String()
	if scale > 0 {
		var rightBuilder strings.Builder
		fracIdx := 0
		for _, ch := range rightPic {
			if ch == 'Z' || ch == '9' {
				var d byte = '0'
				if fracIdx < len(fracStr) {
					d = fracStr[fracIdx]
					fracIdx++
				}
				rightBuilder.WriteByte(d)
			} else {
				rightBuilder.WriteByte(byte(ch))
			}
		}
		combined := leftResult + "." + rightBuilder.String()
		if isNeg {
			// put '-' in first non-space position (simple)
			b := []byte(combined)
			for i, c := range b {
				if c != ' ' && c != ',' {
					b[i] = '-'
					// shift? For exact COBOL sign placement not needed (no negative values in tests)
					break
				}
			}
			combined = string(b)
		}
		return combined
	}
	if isNeg {
		b := []byte(leftResult)
		for i, c := range b {
			if c != ' ' && c != ',' {
				b[i] = '-'
				break
			}
		}
		leftResult = string(b)
	}
	return leftResult
}

func MainPara() {
	WsEofFlag = "N"
	WsTotal = decimal.Zero
	WsGrand = decimal.Zero
	WsNewCount = 0
	WsShipCount = 0
	WsCancelCount = 0
	WsInvalid = 0
	WsBadQty = 0
	loadInput()
	inputIdx = 0
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	curRec.OrId = line[0:5]
	curRec.OrStat = line[5:6]
	qtyStr := line[6:9]
	priceStr := line[9:15]
	curRec.OrQty = parseQtyField(qtyStr)
	curRec.OrPrice = parsePriceField(priceStr)
}

func ProcessPara() {
	WsTotal = decimal.Zero
	if curRec.OrQty == 0 {
		WsBadQty = (WsBadQty + 1) % 100
		fmt.Printf("%s BAD QTY\n", curRec.OrId)
	} else if curRec.OrStat == "N" {
		qtyDec := decimal.NewFromInt(curRec.OrQty)
		raw := qtyDec.Mul(curRec.OrPrice)
		trunc := raw.Truncate(2)
		WsTotal = storeTotal(trunc)
		WsNewCount = (WsNewCount + 1) % 100
		ShowPara()
	} else if curRec.OrStat == "S" {
		qtyDec := decimal.NewFromInt(curRec.OrQty)
		rate, _ := decimal.NewFromString("1.05")
		raw := qtyDec.Mul(curRec.OrPrice).Mul(rate)
		rounded := raw.Round(2)
		WsTotal = storeTotal(rounded)
		WsShipCount = (WsShipCount + 1) % 100
		ShowPara()
	} else if curRec.OrStat == "C" {
		WsCancelCount = (WsCancelCount + 1) % 100
		ShowPara()
	} else {
		WsInvalid = (WsInvalid + 1) % 100
		fmt.Printf("%s BAD STATUS %s\n", curRec.OrId, curRec.OrStat)
	}
	sum := WsGrand.Add(WsTotal)
	WsGrand = storeGrand(sum)
	ReadPara()
}

func ShowPara() {
	WsQtyEd = formatEdited(decimal.NewFromInt(curRec.OrQty), "ZZ9")
	WsPriceEd = formatEdited(curRec.OrPrice, "Z,ZZ9.99")
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZ9.99")
	fmt.Printf("%s %s %s %s %s\n", curRec.OrId, curRec.OrStat, WsQtyEd, WsPriceEd, WsTotalEd)
}

func SummaryPara() {
	WsGrandEd = formatEdited(WsGrand, "Z,ZZZ,ZZZ,ZZ9.99")
	fmt.Printf("NEW: %02d SHIPPED: %02d CANCELLED: %02d\n", WsNewCount, WsShipCount, WsCancelCount)
	fmt.Printf("INVALID: %02d BAD QTY: %02d\n", WsInvalid, WsBadQty)
	fmt.Printf("GRAND TOTAL: %s\n", WsGrandEd)
}

func main() {
	MainPara()
}
